    relatedAyahOrQuote: '"And Allah is the best of planners." — Surah Al-Anfal, Verse 30',
    content: `Days passed in the darkness of the well. Yusuf clung to his faith, remembering his father's words and trusting that Allah had a plan.

One day, a caravan of travelers stopped near the well. They had journeyed from Canaan and were heading to Egypt, seeking water for their camels.

"Look!" one of them called out, "There is water in this well!"

As they lowered their bucket, they were astonished to find a young boy — beautiful, strong, and full of life despite his ordeal.

"Praise be to Allah!" they exclaimed, "This is a boy!"

They pulled Yusuf from the well, amazed by his appearance and demeanor. They saw that he was no ordinary child, and they decided to take him with them to Egypt, where they could sell him as a valuable servant.

Little did they know that this boy was a prophet of Allah, and that his journey to Egypt was part of a divine plan far greater than any of them could imagine.

The caravan continued its journey, and Yusuf found himself traveling to a land he had never seen. He did not know that Egypt would become the place where his dreams would begin to unfold, where he would face new trials, and where Allah's wisdom would shine through every challenge.

As they traveled, Yusuf kept his faith close to his heart. He knew that Allah was with him, guiding his steps, and that every hardship was a step toward the destiny that had been written for him long before he was born.`,
    contentAr: `مكث يوسف في ظلمة البئر أياماً، متمسكاً بإيمانه وواثقاً بأن لله تدبيراً.

ومرّت قافلة مسافرة من كنعان إلى مصر تريد الماء. فلما أرسلوا الدلو وجدوا غلاماً. قالوا: يا بشرى هذا غلام. وأخفوه متاعاً.

فاشتراه عزيز مصر. وما كانوا يعلمون أن هذا الغلام نبي من عند الله، وأن رحلته إلى مصر جزء من قدر أعظم.

وساروا بيوسف إلى أرض لم يرها من قبل. ظلّ يوقن أن الله معه يهديه، وأن كل محنة خطوة إلى ما كُتب له.`,
