    relatedAyahOrQuote: '"And it is He who has made you successors upon the earth." — Surah Al-An\'am, Verse 165',
    content: `During Umar's caliphate, the Muslim armies achieved great victories, conquering vast territories including Persia and parts of the Byzantine Empire. But Umar was not interested in conquest for the sake of power or wealth.

He was concerned with justice, with spreading the message of Islam, and with ensuring that the people in the conquered lands were treated fairly.

When Jerusalem was conquered, Umar himself traveled there to accept the surrender. The Christian patriarch of the city came out to meet him, expecting to see a powerful conqueror in fine robes and surrounded by guards.

Instead, he saw Umar dressed in simple, patched clothes, riding a single camel, sharing it with his servant — taking turns riding while the other walked.

The patriarch was amazed. "This is how your leader travels?" he asked.

Umar's humility and simplicity showed the true character of Islamic leadership — not about showing off power, but about serving Allah and treating people with respect.

In the conquered lands, Umar ensured that the people's rights were protected, their places of worship were respected, and they were treated with justice. He established systems of governance that were fair and equitable.

His example shows us that true victory is not in conquering lands, but in conquering hearts through justice, humility, and respect for all people.`,
    contentAr: `في عهده فُتحت بلاد كثيرة. لما فُتحت القدس جاء عمر بنفسه لاستلامها. استقبله البطريرك فلم يرَ إلا رجلاً بثياب مرقعة على بعير واحد ي交替 مع خادمه. فتعجّب: هكذا يسير أميركم؟

أمر بحماية أهل الذمة وعدالة العيش. النصر عنده فتح القلوب بالعدل والتواضع لا بالبطش.`,
