    relatedAyahOrQuote: '"And do not say about those who are killed in the way of Allah, \'They are dead.\' Rather, they are alive." — Surah Al-Baqarah, Verse 154',
    content: `Umar's caliphate lasted ten years, during which he established systems of justice, expanded the Muslim state, and ensured the welfare of all people under his rule.

But his life came to an end when he was assassinated by a man who held a grudge against him. As Umar lay dying, he was asked if he wanted to appoint his son as the next caliph.

Umar refused, saying: "One dead man is enough for the Ummah." He did not want to establish a dynasty or favor his own family. Instead, he left the choice of the next caliph to a council of the most qualified companions.

Even in his final moments, Umar was thinking of the Muslim community and what was best for them, not for himself or his family.

Before he died, Umar asked to be buried next to the Prophet, peace be upon him, and Abu Bakr. His wish was granted, and he was laid to rest in the same simple grave, showing his humility even in death.

Umar's life was a testament to what it means to be a true leader — someone who is strong yet just, powerful yet humble, a conqueror yet compassionate.

His legacy continues to inspire Muslims today, reminding us that true leadership is about service, justice, and putting the welfare of others before our own interests.

Umar's story teaches us that the greatest honor is not in how long we live or how much we achieve, but in how we live — with justice, humility, and dedication to what is right.`,
    contentAr: `استشهد عمر بعد عشر سنين خلافة. قيل له: أتعيّن ابنك؟ قال: يكفي الأمة موت واحد. فترك الشورى لأهل الحل والعقد. ودفن بجانب النبي وأبي بكر. الشهادة والعدل والتواضع خلاصة سيرته.`,
