    title: 'The Generous Companion',
    estimatedReadingTime: 6,
    reflectionPrompt: 'How do you use your wealth and resources? What does it mean to give generously for the sake of Allah?',
    relatedAyahOrQuote: '"The example of those who spend their wealth in the way of Allah is like a seed which grows seven spikes." — Surah Al-Baqarah, Verse 261',
    content: `Uthman ibn Affan was a wealthy merchant in Makkah, known for his business success and his generous heart. When he accepted Islam, he immediately began using his wealth to support the cause of Allah and help the Muslim community.

During a time of great difficulty in Madinah, when the Muslims were preparing for a crucial battle but lacked resources, Uthman came forward with a generous donation.

He provided camels, horses, weapons, and supplies for the entire army — spending a fortune from his own wealth without hesitation.

The Prophet, peace be upon him, was so pleased with Uthman's generosity that he said: "From this day onward, nothing that Uthman does will harm him."

Uthman's generosity was not limited to times of war. He regularly gave to the poor, helped those in need, and supported the Muslim community in whatever way he could.

He was known for his modesty and humility, despite his wealth. He would often give in secret, not wanting recognition or praise for his charity.

His example teaches us that wealth is a trust from Allah, and that the best use of our resources is to help others and support the cause of truth. True generosity is not about showing off, but about giving sincerely for the sake of Allah.`,
    contentAr: `كان عثمان تاجراً غنياً. لما أسلم بذل ماله في سبيل الله. في غزوة العسرة جهّز جيش العسرة بماله وحمالته. فقال النبي صلى الله عليه وسلم: ما ضرّ عثمان ما عمل بعد اليوم.

كان يعطي سراً ولا يحب الظهور. المال عنده أمانة، وأحسن استخدامه نصر الحق وإغاثة المحتاج.`,
