    content: `Despite Uthman's good leadership and his many contributions to Islam, a group of rebels rose up against him, spreading false accusations and causing unrest.

Uthman had the power to use force against them, but he chose patience instead. He did not want to shed Muslim blood, even to defend himself.

The rebels surrounded his house and cut off his water supply. Still, Uthman remained patient, trusting in Allah and hoping that the situation would be resolved peacefully.

Even when the situation became dangerous, Uthman refused to fight back. He said: "I will not be the first to shed blood in Islam."

When the rebels finally broke into his house, Uthman was reading the Quran. He did not resist, but continued to trust in Allah's wisdom.

As he was being attacked, Uthman's last words were about patience and trust in Allah. He died as a martyr, choosing patience over violence, trusting in Allah's judgment even in his final moments.

Uthman's death was a great loss for the Muslim community, but his example of patience, modesty, and trust in Allah continues to inspire Muslims today.

His story teaches us that sometimes the greatest strength is shown not in fighting back, but in patience and trust in Allah's wisdom. It reminds us that true faith means trusting Allah even in the most difficult circumstances, and that patience in the face of trials is a form of worship.`,
    contentAr: `حاصر المتمردون دار عثمان وحصروا الماء عنه. فلم يقاتل. قال: لا أكون أول من سفك دماً في الإسلام. وكان يقرأ القرآن لما دخلوا عليه فاستشهد صابراً.

قصة عثمان تعلّم أن القوة أحياناً في الصبر والتوكل لا في القتال، وأن الإيمان ثقة بالله حتى في أقسى المحن.`,
