    title: 'Strike with Your Foot',
    estimatedReadingTime: 7,
    reflectionPrompt: 'How do you thank Allah when relief comes after long difficulty?',
    relatedAyahOrQuote: '"Strike with your foot; this is a spring of cool water for washing and drinking." — Surah Sad, Verse 42',
    content: `Allah had seen Ayyub's patience and sincerity throughout the long years of his trial. He had not complained; he had not lost hope. He had only turned to his Lord again and again. So Allah was pleased with him and commanded him: "Strike with your foot; this is a spring of cool water for washing and drinking."

Ayyub did as he was told. He struck the ground with his foot, and a spring gushed forth — cool, clear water. He washed his body with it and drank from it. Through that water and by Allah's power, his health was restored. His skin was healed, his strength returned, and the illness left him. Allah also gave him back his family: new children and a new provision. He was blessed again in this world.

Ayyub fell in prostration, thanking his Lord. He had not lost hope during the long years of trial, and now he had received relief and blessing. He knew that everything — the trial and the relief — was from Allah, and that the best response was gratitude and continued worship.

Allah said of him in the Quran: "Indeed, We found him patient. An excellent servant. Indeed, he was one repeatedly turning back to Allah." The story of Ayyub teaches that patience in trial is never wasted, and that Allah's mercy reaches those who remember Him in hardship and in ease.`,
    contentAr: `لما رأى الله صبر أيوب وصدقه طوال سنين البلاء — لم يشكُ ولم ييأس، بل التفت إلى ربه مرة بعد مرة — رضي عنه وأمره: اركض برجلك هذا مغتسل بارد وشراب. فضرب أيوب الأرض برجله فانفجرت عين ماء بارد عذب. فاغتسل بها وشرب. فبرأ بدنه وعادت قوته وذهب عنه الداء. ورزقه الله أهلاً جديداً ورزقاً حسناً.

فسجد أيوب شكراً. لم ييأس في طول البلاء فجاء الفرج. وعلم أن البلاء والفرج من الله، وأن أحسن الجواب الشكر والعبادة. قال الله فيه: إنا وجدناه صابراً نعم العبد إنه أواب. صبر أيوب يعلّم أن الصبر في البلاء لا يضيع، وأن رحمة الله تلحق من يذكره في الشدة والرخاء.`,
