    content: `After Allah restored Ayyub's health and gave him back his family and provision, Ayyub did not forget what he had been through. He did not grow proud or careless. Instead, his gratitude increased. He knew that every breath, every moment of health, and every blessing was a gift from his Lord.

He used his restored wealth to help others. He fed the poor, supported the needy, and continued to worship Allah with the same devotion he had shown in the depths of his trial. His wife, who had stood by him when no one else would, shared in his gratitude and his charity.

The people who had once turned away from him now saw a man who had been tested and had emerged with his faith stronger. They learned from him that trials are not a sign of Allah's anger, but sometimes a test of faith and a means of raising the believer's rank. They learned that relief follows patience, and that the one who is grateful in ease is the one who truly understood the lesson of hardship.

Ayyub's story ends in blessing, but it is remembered for the long years in between — the years of loss and sickness and patience. Those years taught the world that the best of servants are those who turn to Allah in every state: in health and in sickness, in wealth and in poverty, in ease and in difficulty.`,
    contentAr: `بعد أن عافى الله أيوب ورزقه أهلاً ورزقاً، لم ينس أيوب ما مرّ به. لم يتكبر ولم يغفل. بل زاد شكره. علم أن كل نفس وكل لحظة عافية وكل نعمة هبة من ربه.

واستعمل ماله المعاد في الخير: أطعم الفقراء وساعد المحتاجين وواصل العبادة بنفس الإخلاص الذي أظهره في أعمق البلاء. وزوجته التي وقفت معه حين تنكّب الناس شاركته الشكر والصدقة.

والذين تنكّبوه من قبل رأوا رجلاً ابتُلي فخرج إيمانه أقوى. تعلموا أن البلاء ليس غضب الله بالضرورة، بل قد يكون امتحاناً ورفعة للمؤمن. وتعلموا أن الفرج يأتي بعد الصبر، وأن الشاكر في الرخاء هو من فهم درس الشدة. قصة أيوب تنتهي بنعمة، لكنها تُذكر لسنين الصبر بين البلاء والفرج.`,
