    content: `Despite his vast kingdom, his command over the wind and the jinn, and his wisdom in judgment, Sulaiman never forgot that everything was from Allah. He said: "This is from the favor of my Lord to test me whether I will be grateful or ungrateful. And whoever is grateful — his gratitude is only for himself. And whoever is ungrateful — indeed, my Lord is Free of need and Generous."

He built places of worship and encouraged his people to remember Allah. He judged disputes with fairness, and when he saw that the ant feared his army, he smiled and thanked Allah for the ability to understand even the smallest of creatures. He asked Allah to inspire him to be grateful for His favors and to do righteous deeds that please Him.

When his life was ending, he remained standing in prayer, leaning on his staff, and the jinn did not realize he had died until Allah caused the earth to consume his staff and he fell. So the people learned that even the greatest kingdom in the world is temporary, and that the only lasting success is in obedience and gratitude to Allah.

Sulaiman's story teaches that power and wealth are tests. The one who uses them for justice and for calling others to Allah, and who remains grateful and humble, is the one who passes the test.`,
    contentAr: `رغم ملكه الواسع وتسخير الريح والجن وحكمته في القضاء، لم ينس سليمان أن كل شيء من الله. قال: هذا من فضل ربي ليبلوني أأشكر أم أكفر. ومن شكر فإنما يشكر لنفسه ومن كفر فإن ربي غني كريم.

وبنى المساجد وحث قومه على ذكر الله. وقضى بين الناس بالعدل. ولما سمع النملة تخاف من جنده تبسم وشكر الله على أن علّمه منطق أصغر المخلوقات. وسأل ربه أن يوفقه للشكر على نعمه ولعمل الصالحات التي ترضيه.

ولما حضرته الوفاة بقي قائماً يصلي متكئاً على عصاه. فما علمت الجن أنه مات حتى أكلت الأرض عصاه فسقط. فعلم الناس أن أعظم ملك في الدنيا زائل، وأن النجاح الباقي في الطاعة والشكر لله. قصة سليمان تعلّم أن القوة والمال امتحان. من استخدمهما للعدل والدعوة وبقي شاكراً متواضعاً فقد نجح.`,
