    titleAr: 'ثمرة الثبات',
    titleEn: 'The Fruit of Steadfastness',
    title: 'The Fruit of Steadfastness',
    estimatedReadingTime: 6,
    reflectionPrompt: 'How can one person\'s courage change the hearts of others?',
    relatedAyahOrQuote: '"And whoever saves one life — it is as if he had saved all of humanity." — Surah Al-Maidah, Verse 32',
    content: `After the boy was killed, the people did not forget what they had seen. They had watched a young man stand before the king and choose death rather than deny that Allah is One. They had seen that he had cured the blind man by the permission of Allah. They had seen that he had no fear of the king's power when the truth was at stake.

One by one, and then in groups, they began to believe. The king's authority could kill the body, but it could not kill the truth that had been planted in their hearts. The boy had not led them to the monk — he had kept his promise. But he had led them to something greater: to the recognition that there is no god but Allah, and that the one who holds to that truth is stronger than any tyrant.

The story of the boy and the king is told by the Prophet, peace be upon him, to teach that the believer may face the greatest trials, but his steadfastness is never in vain. It becomes a light for others. And the one who dies for the truth does not truly die; he lives in the memory of Allah and in the faith of those who follow his example.`,
    contentAr: `بعد مقتل الغلام لم ينس الناس ما رأوا. شاهدوا شاباً يقف أمام الملك ويختار الموت على أن ينكر أن الله واحد. ورأوا أنه برأ الأعمى بإذن الله. ورأوا أنه لم يخف سلطان الملك حين كان الحق في الميزان.

فآمنوا واحداً واحداً ثم جماعات. سلطان الملك يقتل الجسد لكنه لا يقتل الحق الذي غُرز في القلوب. الغلام لم يدلّ على الراهب — وفى بعهده. لكنه دلّهم على أعظم: على أن لا إله إلا الله، وأن المتمسك بهذا الحق أقوى من أي طاغية. قصة الغلام والملك يرويها النبي صلى الله عليه وسلم ليعلم أن المؤمن قد يواجه أعظم المحن، لكن ثباته لا يضيع. يصير نوراً لغيرهم. ومن يموت في الحق لا يموت حقاً؛ يبقى في ذكر الله وفي إيمان من يقتدي به.`,
