    estimatedReadingTime: 7,
    reflectionPrompt: 'When have you shown mercy to an animal or someone in need?',
    relatedAyahOrQuote: '"Whoever is merciful to creation, the Most Merciful will have mercy upon him." — Hadith',
    content: `The Prophet, peace be upon him, told his companions a story about a man who had committed many sins. He was not known for his worship or his charity. But one day, this man was walking in the desert and he became very thirsty. His throat was dry and he could find no water. He searched until he came to a well. He climbed down into it, drank his fill, and climbed back out. His thirst was quenched.

As he stood there, he saw a dog. The dog was panting and licking the dry, dusty ground — so thirsty that it was eating mud. The man thought: "This dog is suffering from thirst just as I was. It will die if no one helps it."

He did not walk away. He went back down into the well. He had no bucket, so he took off his shoe, filled it with water, held it in his mouth as he climbed back up, and gave the dog to drink. The dog drank until it was satisfied. The man had shown mercy to a creature that could not thank him and that many people would have ignored.

Allah was pleased with this act of mercy. He forgave the man his sins because of it. The Prophet, peace be upon him, said: "Allah thanked him and forgave him."

The companions asked: "O Messenger of Allah, is there a reward for us in being good to animals?" He said: "In every living being there is a reward." This story teaches that mercy is not limited to people. Showing kindness to any creature — even a dog — can be a cause for Allah's mercy and forgiveness.`,
    contentAr: `حدّث النبي صلى الله عليه وسلم أصحابه عن رجل كان قد أذنب ذنوباً كثيرة. لم يكن معروفاً بعبادة ولا صدقة. لكنه في يوم من الأيام كان يمشي في الصحراء فاشتدّ به العطش. لم يجد ماء. فبحث حتى وجد بئراً. فنزل فيها فشرب حتى روي ثم خرج. فلما وقف رأى كلباً يلهث يلحس الثرى من شدة العطش. فقال الرجل في نفسه: هذا الكلب يعاني من العطش كما عانيت. سيموت إن لم يسق.

فلم يمشِ. نزل البئر مرة أخرى. لم يكن معه دلو فخلع خفه وملأه ماءً وحمله بفيه وهو يصعد وسقى الكلب. فشرب الكلب حتى ارتوى. قد أظهر الرجل رحمة بحيوان لا يستطيع شكره ولو يتجاهله كثيرون.

فرضي الله عن هذا الفعل. فغفر للرجل ذنوبه بسببه. قال النبي صلى الله عليه وسلم: فشكر الله له فغفر له. قال الصحابة: يا رسول الله إن لنا في البهائم أجراً؟ قال: في كل كبد رطبة أجر. الرحمة بكل حي سبب لمغفرة الله.`,
